Environment.UpdateKeepsWhatItDoesNotName.source:
({ before, after, command }) => {
			if (command._tag !== "UpdateEnvironment") {
				return true
			}
			if (after.config === null || before.config === null) {
				return false
			}
			const kept = after.config.networking
			const asked =
				command.changes.config === undefined
					? before.config.networking
					: command.changes.config.networking
			return [
				after.name === (command.changes.name === undefined ? before.name : command.changes.name),
				after.description ===
					(command.changes.description === undefined
						? before.description
						: command.changes.description),
				kept.type === asked.type,
				kept.type !== "limited" ||
					asked.type !== "limited" ||
					(kept.allow_mcp_servers === asked.allow_mcp_servers &&
						kept.allow_package_managers === asked.allow_package_managers),
			].every((ok) => ok)
		}

Session.OpenModelRequestClosedBeforeLeav.source:
({ before, after, events }) => {
			if (
				before._tag !== "Running" ||
				before.open_model_request_id === null ||
				(after._tag === "Running" && after.turn === before.turn)
			) {
				return true
			}
			const endIndex = events.findIndex(
				(event) =>
					event._tag === "span.model_request_end" &&
					event.model_request_start_id === before.open_model_request_id,
			)
			const leaveIndex = events.findIndex(
				(event) =>
					event._tag === "session.status_idle" || event._tag === "session.status_terminated",
			)
			return endIndex >= 0 && (leaveIndex < 0 || endIndex < leaveIndex)
		}

Automation.ScheduledFiringNeedsAnActiveA.source:
({ before, after, command }) => {
			if (command._tag !== "FireAutomation") {
				return true
			}
			return [
				before.status === "active",
				command.activation === before.activation,
				command.scheduled_at > before.last_scheduled_at,
				after.runs === before.runs + 1,
				after.last_scheduled_at === command.scheduled_at,
			].every((ok) => ok)
		}

Automation.AFailedRunPausesOnlyWhenUnrec.source:
({ before, after, command }) => {
			if (command._tag !== "RecordAutomationRunFailed") {
				return true
			}
			return [
				after.status === before.status,
				[command.unrecoverable, command.revision === before.revision].every((ok) => ok),
			].some((ok) => ok)
		}

AutomationRuns.ReservedSlotsCoverLiveAut.source:
(m) => {
			const live = m.Automation.filter((a) =>
				[a.state.status === "active", a.state.status === "paused"].some((ok) => ok),
			)
			return [
				live.every((automation) =>
					m.AutomationCapacity.some((capacity) => capacity.id === capacityOf(automation.state)),
				),
				m.AutomationCapacity.every(
					(capacity) =>
						capacity.state.reserved >=
						live.filter((automation) => capacity.id === capacityOf(automation.state)).length,
				),
			].every((ok) => ok)
		}

AutomationRuns.EveryFiredRunIsReported.source:
(m) =>
			m.Automation.every((a) => {
				const ledger = m.AutomationRunView.find((v) => v.id === a.id)
				return [
					a.state.reported === a.state.runs,
					(ledger === undefined ? 0 : ledger.state.recorded) === a.state.reported,
				].every((ok) => ok)
			})

AutomationRuns.ReservedSlotsEqualLiveAut.source:
(m) => {
			const live = m.Automation.filter((a) =>
				[a.state.status === "active", a.state.status === "paused"].some((ok) => ok),
			)
			return [
				live.every((automation) =>
					m.AutomationCapacity.some((capacity) => capacity.id === capacityOf(automation.state)),
				),
				m.AutomationCapacity.every(
					(capacity) =>
						capacity.state.reserved ===
						live.filter((automation) => capacity.id === capacityOf(automation.state)).length,
				),
			].every((ok) => ok)
		}

AutomationRuns.AFailedRunPausesTheAutoma.source:
(m) =>
			m.Automation.some((automation) =>
				automation.events.some((report, index) => {
					const next = automation.events[index + 1]
					return (
						report._tag === "automation.run_failed" &&
						next?._tag === "automation.paused" &&
						next.reason === report.error.type
					)
				}),
			)

AutomationRuns.EveryRunReportMatchesItsF.source:
(m) =>
			m.Automation.every((automation) =>
				automation.events.every((report) => {
					if (report._tag !== "automation.run_started" && report._tag !== "automation.run_failed") {
						return true
					}
					return automation.events.some(
						(fired) =>
							fired._tag === "automation.fired" &&
							fired.run === report.run &&
							fired.trigger === report.trigger &&
							fired.scheduled_at === report.scheduled_at &&
							(report._tag !== "automation.run_started" || report.session_id === fired.session_id),
					)
				}),
			)
